python3 -c "
import sys, json, re
try:
    tool_input = json.load(sys.stdin)
except:
    sys.exit(0)
path = tool_input.get('file_path', '')

# Validate config/ JSON files
if '/config/' in path and path.endswith('.json'):
    try:
        json.load(open(path))
        print(f'JSON valid: {path}')
    except Exception as e:
        print(f'JSON SYNTAX ERROR in {path}: {e}', file=sys.stderr)
        sys.exit(1)

# Validate _tools/ frontmatter
if '/_tools/' in path and path.endswith('.md'):
    try:
        content = open(path).read()
        required = ['name:', 'url:', 'date_added:', 'peters_pick:', 'create_content:', 'content_created:', 'public:']
        missing = [f for f in required if f not in content]
        if missing:
            print(f'WARNING: _tools/ frontmatter missing required fields: {missing}', file=sys.stderr)
        bool_fields = re.findall(r'(peters_pick|create_content|content_created|public):\s*(.+)', content)
        bad = [(k, v.strip()) for k, v in bool_fields if v.strip() not in ('true', 'false')]
        if bad:
            print(f'WARNING: boolean fields must be true/false, got: {bad}', file=sys.stderr)
    except Exception as e:
        print(f'Could not validate {path}: {e}', file=sys.stderr)
"
